    "Scarcity": {"Explanation": "The email implies urgency by stating that this is a critical update and a recent internal audit flagged a potential vulnerability, creating a sense of urgency to act quickly."},
    "Authority": {"Explanation": "The email establishes authority by mentioning David Chen's role as a Senior Security Analyst from a reputable company, Tech Solutions Inc., giving weight to his request."},
    "Commitment/Consistency": {"Explanation": "The P.S. note references the recipient's past actions (volunteering at a coding workshop) to create a sense of consistency and commitment to security best practices."},
    "Liking": {"Explanation": "The email includes a personal touch by referencing the recipient's past volunteer work, which can build rapport and trust."},
    "Social proof": {"Explanation": "Not present"}
}

